import{r as interop}from"./rolldown-runtime-S-ySWqyJ.js";
import{i as reactFactory,r as runtimeFactory}from"./framework-CXnKph_e.js";
import{t as SeriesHeader}from"./SeriesHeader-DYzr-Hr1.js";
var React=interop(reactFactory(),1),Runtime=runtimeFactory();
const criteria=[{"id":"A1","title":{"tr":"Amaç faaliyet değil, güvenlik sonucu üretmelidir","en":"The goal must produce a safety outcome, not activity"},"essence":{"tr":"Yapılan işi değil, azaltılmak istenen kaybı tanımlayın.","en":"Define the loss to reduce, not merely the work performed."},"explain":{"tr":"Eğitim, denetim ve toplantı birer faaliyettir. Bunlar ancak belirli bir tehlikeyi azaltıyor, bir kontrolü güçlendiriyor veya güvenli davranışı sürdürülebilir kılıyorsa amaca hizmet eder. Bu nedenle faaliyet sayısı, kontrolün durumu ve güvenlik sonucu birlikte izlenmelidir.","en":"Training, audits and meetings are activities. They serve the goal only when they reduce a defined hazard, strengthen a control or make safe work sustainable. Activity counts, control condition and safety outcome should therefore be monitored together."},"why":{"tr":"Faaliyet sayısı artarken gerçek koruma değişmeyebilir. Yanlış ölçü, kurumu çok çalıştığı hâlde aynı tehlikeye açık bırakır.","en":"Real protection may remain unchanged while activity counts rise. A poor measure can leave an active organisation exposed to the same hazard."},"example":{"tr":"“Ayda 20 makine denetimi yapmak” faaliyet hedefidir. “Koruyucusu çalışmayan pres oranını üç ayda %8’den %1’in altına indirmek” ise kontrolle bağlantılı sonuç hedefidir.","en":"“Complete 20 machine inspections each month” is an activity target. “Reduce presses with ineffective guards from 8% to below 1% in three months” is a control-linked outcome target."},"mistake":{"tr":"“Daha çok eğitim verdik, o hâlde daha güvenliyiz” sonucuna, davranış ve kontrol değişikliğini doğrulamadan varmak.","en":"Concluding that more training means greater safety without verifying behaviour or control change."},"question":{"tr":"Bu çalışma hangi olayı, maruziyeti veya sağlık kaybını azaltacak; bunu nasıl anlayacağız?","en":"Which event, exposure or health loss will this work reduce, and how will we know?"},"evidence":{"tr":["İSG politikası ve sonuç hedefleri","Ciddi yaralanma ve ölüm göstergeleri","Mesleki sağlık ve maruziyet göstergeleri","Kritik kontrol performansı","Hedef–sonuç bağlantısı"],"en":["OHS policy and outcome objectives","Serious injury and fatality measures","Occupational-health and exposure measures","Critical-control performance","Objective–outcome link"]}},{"id":"A2","title":{"tr":"Ciddi sonuç potansiyeli ayrı ele alınmalıdır","en":"Serious-outcome potential requires separate attention"},"essence":{"tr":"Gerçekleşen sonuca değil, makul koşullarda ne olabileceğine de bakın.","en":"Consider not only what happened, but what could reasonably have happened."},"explain":{"tr":"Bir olayın hafif atlatılması, olay yolunun güvenli olduğu anlamına gelmez. Enerji, maruziyet veya kontrol kaybı küçük bir koşul farkıyla ölüm ya da kalıcı sağlık kaybı doğurabilecekse kayıt ciddi sonuç potansiyeli taşır. Olay önceliklendirmesi, bu kayıtları rutin kayıtlardan ayırır.","en":"A minor outcome does not prove that the event pathway was safe. A record has serious-outcome potential when the energy, exposure or loss of control could have caused fatal or permanent harm under slightly different conditions. Event triage separates these records from routine ones."},"why":{"tr":"Yalnız gerçekleşen zarara bakmak, şans sayesinde hafif atlatılan ciddi kontrol kayıplarını görünmez kılar.","en":"Looking only at actual harm hides serious control losses that ended mildly through luck."},"example":{"tr":"Forklift, yayaya çarpmadan 20 santimetre önce durdu. Yaralanma yoktur; ancak hız, mesafe ve görüş koşulları biraz farklı olsaydı ölümcül sonuç doğabilirdi. Bu kayıt yüksek öncelikle incelenmelidir.","en":"A forklift stopped 20 centimetres before striking a pedestrian. No one was injured, but a small difference in speed, distance or visibility could have been fatal. The record warrants high-priority review."},"mistake":{"tr":"“Yaralanma olmadı, önemli değil” diyerek yalnız gerçekleşen sonuca göre sınıflandırmak.","en":"Classifying only by actual outcome and saying, “No one was hurt, so it was not important.”"},"question":{"tr":"Bu olay biraz farklı gelişseydi ölüm, ciddi yaralanma veya kalıcı sağlık kaybı oluşabilir miydi?","en":"Could a slightly different course have produced fatality, serious injury or permanent ill health?"},"evidence":{"tr":["Ciddi sonuç potansiyeli ölçütleri","Enerji ve maruziyet bilgileri","Olay önceliklendirme kayıtları","Kritik olay bildirimleri","Potansiyel sonuç değerlendirmesi"],"en":["Serious-outcome-potential criteria","Energy and exposure information","Event-triage records","Critical-event notifications","Potential-consequence assessment"]}},{"id":"A3","title":{"tr":"Yerel hedefler ortak güvenlik amacını zayıflatmamalıdır","en":"Local goals must not undermine the shared safety goal"},"essence":{"tr":"Bir bölümün başarısı, sistemin güvenliğini azaltmamalıdır.","en":"One unit's success must not reduce system safety."},"explain":{"tr":"Üretim, maliyet, hız veya teslim hedefi tek başına makul görünebilir. Ancak bakımın ertelenmesine, bildirimin azalmasına veya güvenli çalışma payının daralmasına yol açıyorsa ortak güvenlik amacına zarar verir. Çatışan hedefler görünür kılınmalı ve güvenli karar ölçütü önceden belirlenmelidir.","en":"Production, cost, speed or delivery targets may appear reasonable in isolation. They undermine the shared safety goal if they defer maintenance, suppress reporting or narrow control margins. Conflicting goals should be made visible and a safe decision rule set in advance."},"why":{"tr":"Çalışan iki zıt başarı ölçüsü arasında kaldığında, günlük baskı çoğu zaman görünür ve kısa vadeli hedefi öne çıkarır.","en":"When a worker faces two opposing definitions of success, daily pressure often favours the visible short-term target."},"example":{"tr":"Bakım ekibine duruş süresini azaltma hedefi verilirken koruyucu testleri için zaman ayrılmazsa, hız hedefi güvenlik hedefini fiilen geçersiz kılar.","en":"If maintenance is told to reduce downtime but receives no time for guard testing, the speed target effectively overrides the safety target."},"mistake":{"tr":"“Önce üretimi tamamlayalım, güvenliği sonra düzeltiriz” yaklaşımını olağan işleyişe dönüştürmek.","en":"Allowing “finish production first, fix safety later” to become normal practice."},"question":{"tr":"Üretim, süre, maliyet veya prim hedeflerinden biri güvenlik müdahalesini geciktiriyor mu?","en":"Is a production, schedule, cost or incentive target delaying the safety intervention?"},"evidence":{"tr":["Birim performans hedefleri","Prim ve teşvik ölçütleri","Bakım erteleme kayıtları","Hedef çatışması ve istisna kararları","Yönetimin gözden geçirmesi"],"en":["Unit performance objectives","Bonus and incentive criteria","Maintenance-deferral records","Goal-conflict and exception decisions","Management review"]}},{"id":"K1","title":{"tr":"Karar sahibi ile uygulama sorumlusu açıkça ayrılmalıdır","en":"Decision owner and action owner must be explicit"},"essence":{"tr":"Kararı kimin vereceğini ve kararı kimin uygulayacağını ayrı ayrı belirtin.","en":"Name separately who decides and who implements."},"explain":{"tr":"Karar sahibi; kontrolü seçmeye, kaynak ayırmaya, tamamlanma tarihini onaylamaya ve gerektiğinde işi durdurmaya yetkili roldür. Uygulama sorumlusu verilen kararı yerine getirir. Aynı kişi iki rolü de üstlenebilir; önemli olan yetkinin ve sorumluluğun belirsiz kalmamasıdır.","en":"The decision owner has authority to select the control, allocate resources, approve the completion date and stop work where necessary. The action owner implements the decision. One person may hold both roles, but authority and responsibility must not remain ambiguous."},"why":{"tr":"Yetkisi olmayan kişiye aksiyon vermek, görünürde sorumlu yaratır; fakat kaynak ve kontrol kararı yine alınamaz.","en":"Assigning action to someone without authority creates apparent ownership while resource and control decisions remain unresolved."},"example":{"tr":"İSG uzmanı pres koruyucusundaki sorunu kaydeder. Bakım müdürü değişimi uygular; bütçe ve duruş kararını ise tesis müdürü verir. Üç rolün adı ve yetkisi kayıtta yer alır.","en":"The OHS specialist records the press-guard problem. Maintenance implements the change, while the plant manager decides budget and downtime. The record names all roles and authorities."},"mistake":{"tr":"Bir toplantı tutanağında yalnız “bakım yapacak” yazmak; bütçe ve duruş kararını verecek kişiyi belirtmemek.","en":"Writing only “maintenance will act” in minutes without naming who decides budget and downtime."},"question":{"tr":"Kontrol, kaynak ve tamamlanma tarihi hakkında gerçekten karar verebilecek kişi kimdir?","en":"Who can actually decide the control, resources and completion date?"},"evidence":{"tr":["Yetki ve imza matrisi","Görev tanımları","Adı belirtilmiş karar sahibi","Bütçe ve iş durdurma yetkisi","Karar ve aksiyon kayıtları"],"en":["Authority and signature matrix","Role descriptions","Named decision owner","Budget and stop-work authority","Decision and action records"]}},{"id":"K2","title":{"tr":"Kritik konunun ne zaman üst kademeye taşınacağı belirlenmelidir","en":"The escalation point for a critical issue must be defined"},"essence":{"tr":"Karar gecikmeden önce, gecikme halinde kimin devreye gireceğini belirleyin.","en":"Before delay occurs, define who intervenes when a decision stalls."},"explain":{"tr":"Üst kademeye taşıma, bir konunun mevcut yetki veya hedef süre içinde çözülememesi hâlinde daha üst karar düzeyine çıkarılmasıdır. Tetikleyici koşul, hedef karar süresi, bildirilecek kişi ve gecikme durumundaki geçici koruma önceden yazılmalıdır.","en":"Escalation moves an issue to a higher decision level when it cannot be resolved within current authority or target time. The trigger, decision time, recipient and temporary protection during delay should be written in advance."},"why":{"tr":"“Gerekirse yönetime bildiririz” ifadesi, ne zamanın gerekli olduğunu tanımlamaz ve kritik konunun beklemesine izin verir.","en":"“We will tell management if necessary” does not define when necessary begins and permits a critical issue to wait."},"example":{"tr":"Koruyucu arızası vardiya içinde giderilemiyorsa makine durdurulur ve konu aynı gün tesis müdürüne taşınır. Kalıcı çözüm kararı 24 saat içinde alınır; bu sırada ekipman kullanılmaz.","en":"If a guard failure cannot be corrected within the shift, the machine is stopped and the matter goes to the plant manager that day. A permanent decision is due within 24 hours; the equipment remains out of use meanwhile."},"mistake":{"tr":"Kritik bulguyu son tarihi geçtikten sonra yalnızca e-posta ile yeniden hatırlatmak.","en":"Merely emailing another reminder after a critical finding is already overdue."},"question":{"tr":"Hangi koşulda, kaç saat içinde, kime bildirim yapılacak ve o zamana kadar nasıl korunacağız?","en":"Under what condition, within how many hours and to whom will we report, and how are people protected meanwhile?"},"evidence":{"tr":["Üst kademeye taşıma matrisi","Tetikleyici koşullar","Hedef karar süreleri","Bildirim zinciri","Geçici kontrol ve gecikme kayıtları"],"en":["Escalation matrix","Trigger conditions","Target decision times","Notification chain","Temporary-control and delay records"]}},{"id":"K3","title":{"tr":"Kritik kararlar ölçüt, katılım ve uzmanlıkla alınmalıdır","en":"Critical decisions require criteria, participation and expertise"},"essence":{"tr":"Kararı makam değil, önceden belirlenmiş ölçütler ve en yakın uzmanlık yönlendirmelidir.","en":"Pre-defined criteria and the closest expertise—not rank alone—should guide the decision."},"explain":{"tr":"İSG birimi riski görünür kılabilir; fakat mühendislik, bakım, üretim ve bütçe kararlarını tek başına veremez. İlgili roller görüşlerini karar öncesinde bağımsız olarak kaydetmeli, karar ölçütleri baştan belirlenmeli ve planın nasıl başarısız olabileceği tartışılmalıdır.","en":"The OHS function can expose risk but cannot decide engineering, maintenance, production and budget alone. Relevant roles should record independent views before discussion, use pre-defined criteria and examine how the plan could fail."},"why":{"tr":"Üst düzey bir kişinin ilk görüşü, diğer kişilerin kanıtlarını söylemesini engelleyebilir. Grup uyumu, karar kalitesiyle karıştırılmamalıdır.","en":"A senior person's first opinion can suppress evidence from others. Group agreement must not be confused with decision quality."},"example":{"tr":"Yeni koruyucu seçilmeden önce operatör, bakım, mühendislik ve İSG temsilcisi gereklilikleri ayrı ayrı yazar. Seçenekler aynı güvenlik, kullanılabilirlik ve bakım ölçütleriyle karşılaştırılır.","en":"Before selecting a new guard, operators, maintenance, engineering and OHS each record requirements. Options are compared using the same safety, usability and maintenance criteria."},"mistake":{"tr":"Toplantıdaki en kıdemli kişinin önerisini, teknik doğrulama yapılmadan ortak karar saymak.","en":"Treating the most senior person's suggestion as a shared decision without technical verification."},"question":{"tr":"Konuya en yakın kişiler bağımsız görüş verdi mi ve seçenekler aynı ölçütlerle karşılaştırıldı mı?","en":"Did the closest people give independent views, and were options compared against the same criteria?"},"evidence":{"tr":["Görev ve sorumluluk matrisi","Önceden belirlenmiş karar ölçütleri","Bağımsız ilk görüşler","Uzman ve çalışan görüşleri","Karar öncesi başarısızlık analizi ve tutanak"],"en":["Responsibility matrix","Pre-defined decision criteria","Independent initial views","Expert and worker input","Pre-mortem and decision record"]}},{"id":"Y1","title":{"tr":"Kritik iş yükü mevcut kapasiteyi aşmamalıdır","en":"Critical demand must not exceed available capacity"},"essence":{"tr":"Yoğunluğu değil, talep ile karşılanabilir kapasite arasındaki farkı ölçün.","en":"Measure the gap between demand and deliverable capacity, not busyness."},"explain":{"tr":"Kapasite yalnız çalışan sayısı değildir; kullanılabilir zaman, yetkinlik, ekipman ve karar erişimini de kapsar. Kritik işler giderek daha uzun bekliyor, birikiyor veya tek kişiye bağımlı kalıyorsa talep kapasiteyi aşmış olabilir. Çok çalışan bir ekip, sırf yoğun olduğu için kısıt değildir.","en":"Capacity is more than headcount; it includes available time, competence, equipment and access to decisions. If critical work ages, accumulates or depends on one person, demand may exceed capacity. A busy team is not a constraint merely because it works hard."},"why":{"tr":"Sürekli fazla çalışma kısa süreli açığı gizleyebilir; fakat hata olasılığını, bekleme süresini ve tek kişiye bağımlılığı artırır.","en":"Persistent overtime can hide a shortfall while increasing error likelihood, waiting time and dependence on individuals."},"example":{"tr":"Bir bakım mühendisi aynı hafta 40 kritik aksiyon, arıza müdahalesi ve periyodik kontrol yürütüyorsa sorun kişisel hız değil, iş yükü–kapasite uyumsuzluğu olabilir.","en":"If one maintenance engineer handles 40 critical actions, breakdowns and inspections in one week, the issue may be demand–capacity mismatch rather than personal speed."},"mistake":{"tr":"Gecikmeyi yalnız “daha hızlı çalışın” talimatıyla çözmeye çalışmak.","en":"Trying to solve delay only by telling people to work faster."},"question":{"tr":"Kritik işler neden bekliyor: iş miktarı mı fazla, yetkinlik mi eksik, yoksa kapasite başka işlere mi ayrılıyor?","en":"Why is critical work waiting: too much demand, missing competence or capacity allocated elsewhere?"},"evidence":{"tr":["İş yükü–kapasite karşılaştırması","Kritik iş kuyruğu ve bekleme süresi","Fazla çalışma ve erteleme kayıtları","Yetkinlik matrisi","Tek kişiye bağımlılık"],"en":["Demand–capacity comparison","Critical-work queue and ageing","Overtime and deferral records","Competence matrix","Single-person dependency"]}},{"id":"Y2","title":{"tr":"Kritik müdahale kaynak veya yedek kapasite beklememelidir","en":"Critical intervention must not wait for resources or backup capacity"},"essence":{"tr":"Kararla birlikte insanı, bütçeyi, malzemeyi ve alternatif yolu güvenceye alın.","en":"Secure people, budget, materials and an alternative route with the decision."},"explain":{"tr":"Kararın alınması tek başına riski azaltmaz. Uygulama için insan, bütçe, satın alma, mühendislik ve devreye alma kapasitesi zamanında sağlanmalıdır. Tek bir kişi, tedarikçi veya ekipmanın kaybı kritik işlevi durduruyorsa makul bir yedek yol gerekir.","en":"A decision alone does not reduce risk. People, budget, procurement, engineering and commissioning capacity must arrive in time. A reasonable backup route is needed when loss of one person, supplier or asset stops a critical function."},"why":{"tr":"Kaynağı tanımlanmayan aksiyon, yapılacaklar listesinde görünür; fakat sahada koruma üretmez.","en":"An action without secured resources appears on a list but produces no protection in the field."},"example":{"tr":"Koruyucu siparişinin sekiz hafta süreceği biliniyorsa yalnız sipariş açılmaz. Bu süre için güvenli durdurma, başka ekipmanda üretim veya onaylı geçici koruma planlanır.","en":"If a new guard takes eight weeks, placing an order is not enough. Safe shutdown, alternative equipment or an approved temporary control is planned for the waiting period."},"mistake":{"tr":"Bütçe, teslim süresi ve geçici koruma belirlenmeden aksiyona son tarih vermek.","en":"Setting a due date without deciding budget, delivery time and temporary protection."},"question":{"tr":"Gerekli kişi, bütçe, malzeme veya tedarik kullanılamazsa güvenli alternatifimiz nedir?","en":"What is the safe alternative if the required person, budget, material or supply is unavailable?"},"evidence":{"tr":["Bütçe ve satın alma onayı","Teslim ve devreye alma süresi","Alternatif tedarik veya ekipman","Yedek yetkin kişi","Geçici kontrol ve acil kapasite planı"],"en":["Budget and procurement approval","Delivery and commissioning time","Alternative supply or equipment","Competent backup person","Temporary-control and surge-capacity plan"]}},{"id":"Y3","title":{"tr":"Her İSG faaliyetinin amaca katkısı açıklanmalıdır","en":"Every OHS activity needs an explainable contribution to the goal"},"essence":{"tr":"Bir işin gerekli olması, amaca nasıl katkı sağladığıyla gösterilmelidir.","en":"Show how necessary work contributes to the goal."},"explain":{"tr":"Rapor, toplantı, form ve prosedür gerekli olabilir. Ancak zaman ve dikkati tüketirken saha doğrulamasını geciktiriyorsa yeniden tasarlanmalıdır. Her faaliyet için şu bağ kurulmalıdır: amaç → etki mekanizması → beklenen kanıt. Katkısı açıklanamayan iş hemen kaldırılmaz; önce yasal, teknik ve öğrenme işlevi doğrulanır.","en":"Reports, meetings, forms and procedures may be necessary. If they consume time and attention while delaying field verification, they should be redesigned. Link each activity through goal → mechanism → expected evidence. Work with no explainable contribution is not removed automatically; its legal, technical and learning function is checked first."},"why":{"tr":"Araç amaca hizmet etmiyorsa kendi başına başarı değildir. Gereksiz iş, kritik müdahalenin zamanını ve dikkatini tüketebilir.","en":"A tool is not a success in itself if it does not serve the goal. Unnecessary work can consume time and attention needed for critical intervention."},"example":{"tr":"Aynı bulgu üç ayrı tabloya giriliyor, fakat hiçbiri karar sahibine gitmiyorsa kayıt işi artar; müdahale hızlanmaz. Tek kayıt ve açık karar akışı daha etkilidir.","en":"If the same finding enters three spreadsheets but none reaches a decision owner, administration grows without faster intervention. One record and a clear decision flow are more effective."},"mistake":{"tr":"Uzun süredir yapıldığı veya denetimde sorulabileceği için bir faaliyetin otomatik olarak değer ürettiğini varsaymak.","en":"Assuming an activity creates value because it has always been done or might be requested in an audit."},"question":{"tr":"Bu faaliyet hangi güvenlik sonucunu, hangi mekanizmayla iyileştiriyor ve bunu gösteren kanıt nedir?","en":"Which safety outcome does this activity improve, by what mechanism, and what evidence shows it?"},"evidence":{"tr":["Faaliyet ve rapor envanteri","Amaç–Katkı Testi","Zaman kullanım analizi","Sadeleştirilen veya birleştirilen işler","Sahaya ayrılan zaman"],"en":["Activity and reporting inventory","Purpose–Contribution Test","Time-use analysis","Simplified or combined work","Time available for field work"]}},{"id":"B1","title":{"tr":"Dağınık bilgiler ortak bir öncelik görünümünde birleşmelidir","en":"Fragmented information must form one priority picture"},"essence":{"tr":"Aynı tehlikeye ait farklı kayıtları birlikte görün.","en":"See different records about the same hazard together."},"explain":{"tr":"Kaza, ramak kala, tehlikeli durum, iş hijyeni, sağlık gözetimi, bakım ve denetim verileri ayrı sistemlerde kalabilir. Ortak tanımlar ve eşleştirme ölçütleri olmadan aynı sorunun tekrarlayan işaretleri fark edilmez. Birleşik görünüm, kayıtları tek dosyada toplamak değil, aynı karara bağlamaktır.","en":"Incident, near-miss, hazard, hygiene, health-surveillance, maintenance and audit data may remain in separate systems. Without common definitions and matching criteria, repeated signs of the same problem are missed. An integrated view means linking records to one decision, not merely storing them in one file."},"why":{"tr":"Her bölüm kendi parçasını görürken hiç kimse tehlikenin toplam örüntüsünü görmeyebilir.","en":"Each function may see its part while no one sees the complete hazard pattern."},"example":{"tr":"Operatör koruyucu arızasını bildirir, bakım aynı parçanın sık bozulduğunu kaydeder, denetim benzer uygunsuzluk bulur. Kayıtlar eşleşmezse üç ayrı küçük sorun gibi görünür.","en":"An operator reports a failed guard, maintenance records repeated part failures and an audit finds a similar issue. Without linkage, they appear as three small problems."},"mistake":{"tr":"Yeni bir gösterge paneli kurmayı, ortak tanım ve karar sorumlusu oluşturmadan çözüm saymak.","en":"Treating a new dashboard as the solution without shared definitions and a decision owner."},"question":{"tr":"Bu tehlikeye ait olay, bakım, maruziyet ve çalışan bildirimlerini tek bir karar görünümünde görebiliyor muyuz?","en":"Can we see incident, maintenance, exposure and worker reports about this hazard in one decision view?"},"evidence":{"tr":["Ortak veri sözlüğü","Birleşik kayıt veya bağlantılı sistem","Ortak sınıflandırma","Mükerrer kayıt kontrolü","Veri ve karar sorumluları"],"en":["Shared data dictionary","Integrated register or linked system","Common classification","Duplicate control","Data and decision owners"]}},{"id":"B2","title":{"tr":"Zayıf işaretler, gecikme ve kapasite doygunluğu görünür olmalıdır","en":"Weak signs, delay and capacity saturation must be visible"},"essence":{"tr":"Zarar oluşmadan önce biriken küçük bozulmaları izleyin.","en":"Monitor accumulating small deterioration before harm occurs."},"explain":{"tr":"Tekrarlayan küçük sapmalar, uzayan bekleme süreleri, geçici istisnalar ve dolan iş kuyrukları yaklaşan kontrol kaybının erken işaretleri olabilir. Olay yaşanmaması bu koşulların güvenli olduğunu kanıtlamaz. Yönetim yalnız açık aksiyon sayısını değil, işlerin yaşını ve tekrar örüntüsünü de görmelidir.","en":"Repeated small deviations, longer waiting times, temporary exceptions and full work queues may be early signs of approaching control loss. Absence of an event does not prove these conditions safe. Management should see work age and repetition patterns, not only the number of open actions."},"why":{"tr":"Küçük sapmalar sonuç doğurmadıkça kabul edilmeye başlanabilir. Zamanla istisna, yeni normal hâline gelir.","en":"Small deviations may become accepted when they cause no immediate harm. Over time, the exception becomes the new normal."},"example":{"tr":"Koruyucu sensörü ayda bir kez arıza verirken geçici sıfırlama yapılır. Arıza sıklığı haftalığa çıktığında bile olay olmamıştır; ancak güvenlik marjı belirgin biçimde azalmıştır.","en":"A guard sensor fails monthly and is temporarily reset. Even when failure becomes weekly, no event may occur, but the safety margin has clearly eroded."},"mistake":{"tr":"Yalnız kaza sayısı düşüyorsa kontrol sisteminin sağlıklı olduğunu varsaymak.","en":"Assuming the control system is healthy because injury counts are low."},"question":{"tr":"Tekrarlayan sapmalar, bekleme süreleri ve geçici çözümler zaman içinde artıyor mu?","en":"Are repeated deviations, waiting times and temporary fixes increasing over time?"},"evidence":{"tr":["Karar ve uygulama kuyrukları","Bekleme süresi eğilimi","Tekrarlayan sapma kayıtları","Geçici istisnalar","Kapasite uyarıları ve yönetim incelemesi"],"en":["Decision and execution queues","Ageing trend","Repeated-deviation records","Temporary exceptions","Capacity alerts and management review"]}},{"id":"B3","title":{"tr":"Analiz, karara ve doğrulanabilir eyleme dönüşmelidir","en":"Analysis must become a decision and verifiable action"},"essence":{"tr":"Her analiz sonunda kim, neyi, ne zaman ve hangi koşulda yapacağını bilmelidir.","en":"Every analysis should end with who will do what, when and under which condition."},"explain":{"tr":"Rapor veya grafik tek başına koruma sağlamaz. Analiz; karar sahibi, uygulanacak kontrol, gerekli kaynak, tamamlanma tarihi, tetikleyici koşul ve etkinlik doğrulaması bulunan bir karara bağlanmalıdır. Kritik belirsizliklerde “X olursa Y kişi Z eylemini başlatır” biçimindeki koşul–eylem planı kullanılabilir.","en":"A report or chart does not protect by itself. Analysis must lead to a decision naming the owner, control, resources, completion date, trigger and effectiveness check. Under critical uncertainty, use a condition–action plan: “If X occurs, person Y starts action Z.”"},"why":{"tr":"Sorumlusu ve tetikleyicisi olmayan öneri, herkesin bildiği fakat kimsenin başlatmadığı bir işe dönüşür.","en":"A recommendation without an owner and trigger becomes work everyone knows about but no one starts."},"example":{"tr":"“Koruyucu iyileştirilecek” yerine “Bakım müdürü onaylı koruyucuyu 15 Eylül’e kadar kuracak; mühendislik kurulumdan sonra üç çalışma koşulunda fonksiyon testi yapacak” yazılır.","en":"Replace “the guard will be improved” with “the maintenance manager installs the approved guard by 15 September; engineering tests it under three operating conditions.”"},"mistake":{"tr":"“Gereği yapılacaktır” ifadesini karar ve aksiyon kaydı olarak kabul etmek.","en":"Accepting “necessary action will be taken” as a decision and action record."},"question":{"tr":"Analiz, yetkili karar sahibini, kaynağı, tarihi ve etkinlik kontrolünü belirledi mi?","en":"Did the analysis define an authorised decision owner, resources, date and effectiveness check?"},"evidence":{"tr":["Karar kaydı","Adı belirtilmiş sorumlu ve tarih","Koşul–eylem planı","Kaynak kararı","Kapanış ve etkinlik doğrulaması"],"en":["Decision record","Named owner and date","Condition–action plan","Resource decision","Close-out and effectiveness verification"]}},{"id":"U1","title":{"tr":"Ciddi olay yolu ve kritik kontroller belirlenmelidir","en":"Serious-event pathways and critical controls must be defined"},"essence":{"tr":"Önlemek istediğiniz ciddi olayı ve onu durdurması gereken kontrolleri açıkça gösterin.","en":"Show the serious event to prevent and the controls that must stop it."},"explain":{"tr":"Ciddi olay yolu; tehlikenin kontrol kaybından zarara nasıl ilerleyebileceğini gösterir. Kritik kontrol, bu yolu önleyen veya sonucu önemli ölçüde azaltan ve başarısızlığı riski belirgin artıran kontroldür. Her prosedür, eğitim veya kişisel koruyucu donanım kritik kontrol değildir; seçim olay senaryosuna göre yapılır.","en":"A serious-event pathway shows how a hazard can progress from loss of control to harm. A critical control prevents the pathway or materially limits the consequence, and its failure significantly increases risk. Not every procedure, course or item of PPE is critical; selection depends on the event scenario."},"why":{"tr":"Kritik olan birkaç kontrol belirlenmezse dikkat çok sayıdaki düşük etkili faaliyete dağılır.","en":"If the few critical controls are not identified, attention disperses across many lower-impact activities."},"example":{"tr":"Presin hareketli bölgesine elin girmesi ciddi olay yoludur. Sabit koruyucu ve koruyucu açıldığında hareketi güvenli biçimde durduran kilitleme sistemi kritik kontrol olabilir.","en":"A hand entering a moving press is a serious-event pathway. A fixed guard and an interlock that safely stops motion when opened may be critical controls."},"mistake":{"tr":"Kontrol listesindeki her önlemi eşit derecede kritik saymak.","en":"Treating every measure on a checklist as equally critical."},"question":{"tr":"Önlemek istediğimiz ciddi olay nedir ve hangi kontrol başarısız olursa olay yolu açılır?","en":"What serious event are we preventing, and which control failure opens the pathway?"},"evidence":{"tr":["Ciddi olay senaryosu","Papyon analizi","Kritik kontrol seçim ölçütleri","Kritik kontrol listesi ve sahibi","Çalışan ve uzman görüşleri"],"en":["Serious-event scenario","Bow-tie analysis","Critical-control selection criteria","Critical-control register and owner","Worker and expert input"]}},{"id":"U2","title":{"tr":"Kritik kontrolün başarı ölçütü açık olmalıdır","en":"A critical control needs an explicit success standard"},"essence":{"tr":"“Kontrol var” demeyin; ne zaman yeterli koruma sağladığını tanımlayın.","en":"Do not say only that a control exists; define when it provides adequate protection."},"explain":{"tr":"Performans standardı; kontrolün görevi, çalışması gereken koşullar, kabul edilebilir sınır, doğrulama yöntemi, doğrulama sıklığı ve sorumlu kişiyi tanımlar. Kabul edilemez sapma oluştuğunda yapılacak müdahale veya iş durdurma kararı da önceden belirlenmelidir.","en":"A performance standard defines the control's function, operating conditions, acceptable limit, verification method, frequency and responsible person. The response or stop-work decision for unacceptable deviation should also be defined in advance."},"why":{"tr":"Ölçüt yoksa aynı kontrol bir kişi tarafından yeterli, başka biri tarafından yetersiz kabul edilebilir.","en":"Without a standard, one person may accept a control that another considers inadequate."},"example":{"tr":"“Lokal emiş çalışıyor” yerine “ölçüm noktasında en az belirlenen yakalama hızı sağlanacak; değer sınırın altındaysa iş duracak ve bakım çağrılacak” denir.","en":"Replace “local exhaust works” with “the specified minimum capture velocity is maintained; work stops and maintenance is called below the limit.”"},"mistake":{"tr":"Kontrolün yalnız kurulu veya açık olduğunu kontrol edip koruyucu işlevini ölçmemek.","en":"Checking only that a control is installed or switched on without measuring its protective function."},"question":{"tr":"Bu kontrolün yeterli çalıştığını hangi ölçümle anlayacağız ve hangi sapmada işi durduracağız?","en":"What measure shows adequate performance, and at what deviation will work stop?"},"evidence":{"tr":["Performans standardı","Teknik sınır ve kabul ölçütü","Doğrulama yöntemi ve sıklığı","Kontrol listesi ve sorumlu","Sapma ve iş durdurma kayıtları"],"en":["Performance standard","Technical limit and acceptance criterion","Verification method and frequency","Checklist and owner","Deviation and stop-work records"]}},{"id":"U3","title":{"tr":"Kritik kontrol değişen koşullarda da çalışmalıdır","en":"Critical controls must work under changing conditions"},"essence":{"tr":"Kontrolü yalnız normal günde değil, zorlandığı koşullarda da doğrulayın.","en":"Verify the control not only on a normal day, but under demanding conditions."},"explain":{"tr":"Kontrolün sahada bulunması yeterli değildir. Normal işletme, vardiya değişimi, bakım, arıza, yoğun talep, enerji kesintisi ve olağandışı koşullarda gerektiği anda çalıştığı güvenli testlerle gösterilmelidir. Başarısızlık hâli için yedek yanıt ve iş durdurma yetkisi bulunmalıdır.","en":"Physical presence is not enough. Safe tests should show that the control works when needed during normal operation, shift change, maintenance, failure, peak demand, power loss and abnormal conditions. A backup response and stop-work authority are required for failure."},"why":{"tr":"Bir kontrol en çok ihtiyaç duyulduğu anda arıza veriyorsa, normal koşuldaki varlığı sahte güven oluşturur.","en":"If a control fails when most needed, its normal-condition presence creates false assurance."},"example":{"tr":"Koruyucu kilidi boşta çalışırken test edilir; ayrıca üretim hızı, ayar değişimi ve enerji geri gelmesi gibi güvenli test senaryolarında makineyi beklenen biçimde durdurduğu doğrulanır.","en":"A guard interlock is tested at idle and under safe scenarios such as production speed, setup change and power restoration to confirm the expected stop."},"mistake":{"tr":"Bakım etiketi veya periyodik kontrol tarihi bulunduğu için kontrolün işlevsel olduğunu varsaymak.","en":"Assuming a control is functional because a maintenance label or inspection date exists."},"question":{"tr":"Kontrolü hangi gerçekçi koşullarda test ettik ve çalışmazsa güvenli yedek yanıtımız nedir?","en":"Under which realistic conditions did we test the control, and what is the safe backup if it fails?"},"evidence":{"tr":["Fonksiyon ve saha testleri","Bakım ve arıza kayıtları","Değişen koşul senaryoları","Güvenilirlik eğilimi","Yedek yanıt ve iş durdurma planı"],"en":["Functional and field tests","Maintenance and failure records","Changed-condition scenarios","Reliability trend","Backup response and stop-work plan"]}},{"id":"O1","title":{"tr":"“Dikkatsizlik” incelemeyi bitiren bir neden değildir","en":"“Carelessness” is not an investigation endpoint"},"essence":{"tr":"Davranışı etiketlemek yerine, davranışı üreten koşulları açıklayın.","en":"Explain the conditions that produced behaviour instead of labelling it."},"explain":{"tr":"“Dikkatsizlik” ne olduğunu adlandırır; neden olduğunu açıklamaz. İnceleme, kişinin o anda gördüğü bilgiyi, iş yükünü, zaman baskısını, ekipman tasarımını, hedef çatışmalarını ve prosedür ile gerçek iş arasındaki farkı araştırmalıdır. Bu yaklaşım kişisel sorumluluğu kaldırmaz; tekrarın önlenebileceği sistem noktalarını bulur.","en":"“Carelessness” names what happened but does not explain why. Review should examine the information available at the time, workload, time pressure, equipment design, goal conflicts and the gap between procedure and real work. This does not remove accountability; it identifies system points where recurrence can be prevented."},"why":{"tr":"Kişiyi değiştirip aynı koşulları korumak, bir sonraki kişinin benzer davranışta bulunmasını engellemez.","en":"Replacing a person while preserving the same conditions does not prevent similar behaviour by the next person."},"example":{"tr":"Operatör koruyucuyu devre dışı bıraktıysa yalnız “kurala uymadı” denmez. Koruyucu üretimi sık durduruyor mu, arıza bildirimi yanıtsız mı kalıyor, hedef baskısı var mı ve güvenli alternatif uygulanabilir mi diye bakılır.","en":"If an operator bypassed a guard, do not stop at “the rule was broken.” Examine nuisance stops, unanswered fault reports, target pressure and whether a safe alternative was workable."},"mistake":{"tr":"Son nedeni “insan hatası” olarak yazıp tasarım ve yönetim koşullarını incelememek.","en":"Recording “human error” as the final cause without examining design and management conditions."},"question":{"tr":"Bu davranış o anda neden makul veya gerekli görünmüş olabilir ve hangi sistem koşulları bunu kolaylaştırdı?","en":"Why might this behaviour have appeared reasonable or necessary at the time, and which system conditions enabled it?"},"evidence":{"tr":["Çalışan görüşmesi","Gerçek işin saha gözlemi","İş yükü ve zaman analizi","Prosedür–uygulama karşılaştırması","Tasarım ve kontrol eksiklikleri"],"en":["Worker interview","Observation of work as done","Workload and time analysis","Procedure–practice comparison","Design and control gaps"]}},{"id":"O2","title":{"tr":"Bildirim kadar yönetimin yanıtı da güvenli olmalıdır","en":"Management response matters as much as reporting"},"essence":{"tr":"İnsanlar konuşabilmeli; yönetim de bildirimi zamanında ve adil biçimde karşılamalıdır.","en":"People must be able to speak up, and management must respond promptly and fairly."},"explain":{"tr":"Psikolojik güvenlik, çalışanların soru, hata ve kaygılarını küçük düşürülme veya ceza korkusu olmadan söyleyebilmesidir. Adil kültür, dürüst hata, riskli davranış ve kasıtlı ihlali aynı biçimde değerlendirmez. Açıklık, düşük standart anlamına gelmez; öğrenme ile hesap verebilirlik birlikte yürür.","en":"Psychological safety allows workers to raise questions, errors and concerns without fear of humiliation or punishment. A just culture does not treat honest error, risk-taking behaviour and intentional violation identically. Openness does not mean low standards; learning and accountability work together."},"why":{"tr":"Çalışan bildirimden sonra zarar göreceğini düşünürse erken işaretler yönetim sistemine hiç girmez.","en":"If workers expect harm after reporting, early signs never enter the management system."},"example":{"tr":"Operatör koruyucu arızasını bildirince vardiyası değiştirilir veya “üretimi aksatan kişi” olarak görülürse diğer çalışanlar benzer sorunları saklar. Yönetim yanıtı bildirim kültürünü belirler.","en":"If a worker reporting a guard fault is moved to another shift or labelled a blocker, others will hide similar problems. Management response shapes reporting culture."},"mistake":{"tr":"İhbar hattı kurulduğu için çalışanların güvenle konuşabildiğini varsaymak.","en":"Assuming that a reporting hotline proves people can speak safely."},"question":{"tr":"Bir çalışan iyi niyetle sorun bildirirse ne olacağını biliyor ve olumsuz karşılıktan korunacağına güveniyor mu?","en":"Does a worker know what follows a good-faith report and trust that adverse treatment will not follow?"},"evidence":{"tr":["Çalışan görüşmeleri","Bildirim ve yanıt süreleri","Adil kültür ilkeleri","Misilleme ve şikâyet kayıtları","Bildirim sahibine geri bildirim"],"en":["Worker interviews","Reporting and response times","Just-culture principles","Retaliation and concern records","Feedback to the reporter"]}},{"id":"O3","title":{"tr":"Öğrenme benzer işlere yayılmalı ve etkisi doğrulanmalıdır","en":"Learning must spread to similar work and its effect be verified"},"essence":{"tr":"Dersi yalnız olayın olduğu yerde bırakmayın; benzer işlere aktarın ve işe yaradığını gösterin.","en":"Do not leave learning where the event occurred; transfer it and show that it works."},"explain":{"tr":"Öğrenme yalnız kazalardan değil, ramak kala olaylardan, tatbikatlardan, değişikliklerden ve çalışanların işi güvenli sürdürmek için yaptığı başarılı uyarlamalardan da elde edilir. Çözüm benzer ekipman ve bölümlere aktarılmalı; uygulandığı ve riski gerçekten azalttığı doğrulanmalıdır.","en":"Learning comes not only from accidents, but from near misses, drills, changes and successful adaptations workers use to keep work safe. Transfer the solution to similar equipment and areas, then verify implementation and actual risk reduction."},"why":{"tr":"Aynı tasarım veya iş yöntemi başka yerde sürüyorsa tek noktadaki düzeltme kurumsal öğrenme değildir.","en":"If the same design or method persists elsewhere, a local correction is not organisational learning."},"example":{"tr":"Bir presteki koruyucu sorunu giderildikten sonra aynı modeldeki bütün presler taranır. Yeni koruyucular kurulur, fonksiyon testleri yapılır ve üç ay sonra arıza eğilimi yeniden incelenir.","en":"After correcting one press guard, all presses of the same model are screened. New guards are installed, function-tested and failure trends reviewed three months later."},"mistake":{"tr":"Aksiyon kapandığında öğrenmenin tamamlandığını varsaymak; benzer yerleri ve etkinliği kontrol etmemek.","en":"Assuming learning is complete when an action closes without checking similar locations and effectiveness."},"question":{"tr":"Bu öğrenme nerelerde daha uygulanmalı ve çözümün işe yaradığını hangi kanıtla doğrulayacağız?","en":"Where else must this learning be applied, and what evidence will verify that it works?"},"evidence":{"tr":["Benzer iş ve ekipman listesi","Yatay yayılım planı","Değişiklik yönetimi","Tamamlanma doğrulaması","Etkinlik kontrolü ve tekrar eğilimi"],"en":["Similar-work and equipment list","Horizontal-deployment plan","Management of change","Completion verification","Effectiveness check and recurrence trend"]}}];
const groups=[{"key":"purpose","name":{"tr":"01 · AMAÇ VE ÖNCELİK","en":"01 · GOAL & PRIORITY"},"desc":{"tr":"Yapılan işlerin ortak güvenlik sonucuna hizmet edip etmediğini inceler.","en":"Examines whether work serves the shared safety outcome."},"lens":{"tr":"Buradaki temel soru şudur: Çok iş yapıyor muyuz, yoksa doğru güvenlik sonucunu mu üretiyoruz?","en":"The central question is: are we doing a lot of work, or producing the right safety outcome?"},"ids":["A1","A2","A3"]},{"key":"decision","name":{"tr":"02 · KARAR ALMA VE YÖNETİM","en":"02 · DECISION-MAKING & MANAGEMENT"},"desc":{"tr":"Yetkinin, karar süresinin, katılımın ve karar kalitesinin yeterli olup olmadığını inceler.","en":"Examines whether authority, decision time, participation and decision quality are adequate."},"lens":{"tr":"Bir tehlikeyi bilmek yetmez. Yetkili bir kişi, zamanında ve uygulanabilir bir karar vermelidir.","en":"Knowing a hazard is not enough. An authorised person must make a timely, workable decision."},"ids":["K1","K2","K3"]},{"key":"capacity","name":{"tr":"03 · KAYNAK VE KAPASİTE","en":"03 · RESOURCE & CAPACITY"},"desc":{"tr":"İnsan, zaman, bütçe, uzmanlık ve yedek kapasitenin ihtiyacı karşılayıp karşılamadığını inceler.","en":"Examines whether people, time, budget, expertise and backup capacity meet the need."},"lens":{"tr":"Doğru karar verilmiş olsa bile gerekli insan, zaman veya bütçe yoksa müdahale gerçekleşmez.","en":"Even a correct decision will not become an intervention without the necessary people, time or budget."},"ids":["Y1","Y2","Y3"]},{"key":"information","name":{"tr":"04 · BİLGİ VE ANALİZ","en":"04 · INFORMATION & ANALYSIS"},"desc":{"tr":"Verinin görünür bir önceliğe, karara ve uygulanabilir eyleme dönüşüp dönüşmediğini inceler.","en":"Examines whether data becomes a visible priority, a decision and an implementable action."},"lens":{"tr":"Veri, doğru kişiye doğru zamanda ulaşmıyor ve karar doğurmuyorsa yalnızca kayıt olarak kalır.","en":"Data remains only a record if it does not reach the right person in time and produce a decision."},"ids":["B1","B2","B3"]},{"key":"controls","name":{"tr":"05 · UYGULAMA VE KRİTİK KONTROL","en":"05 · EXECUTION & CRITICAL CONTROL"},"desc":{"tr":"Ciddi olayları önlemesi gereken kritik kontrollerin sahada gerçekten çalışıp çalışmadığını inceler.","en":"Examines whether critical controls intended to prevent serious events actually work in the field."},"lens":{"tr":"Bir kontrolün prosedürde yazması veya ekipmanın üzerinde bulunması, koruma sağladığını kanıtlamaz.","en":"A control written in a procedure or fitted to equipment is not proof that it provides protection."},"ids":["U1","U2","U3"]},{"key":"learning","name":{"tr":"06 · ÖĞRENME VE KÜLTÜR","en":"06 · LEARNING & CULTURE"},"desc":{"tr":"Sorunların konuşulabilmesini, olayların sistem yönüyle incelenmesini ve öğrenmenin yayılmasını inceler.","en":"Examines speaking up, system-oriented review and the spread of learning."},"lens":{"tr":"İnsanlar konuşamıyorsa sistem erken uyarıları kaybeder; yalnız kişiyi suçluyorsa aynı koşulları korur.","en":"If people cannot speak up, the system loses early warnings; if it only blames individuals, it preserves the same conditions."},"ids":["O1","O2","O3"]}];
const coreGlossary=[{"term":{"tr":"İş sağlığı ve güvenliği (İSG)","en":"Occupational health and safety (OHS)"},"definition":{"tr":"Çalışanın iş nedeniyle yaralanmasını, hastalanmasını veya sağlığını kaybetmesini önlemeye yönelik yönetim ve uygulama alanıdır.","en":"The management and practice of preventing work-related injury, illness and loss of health."},"example":{"tr":"Makine koruyucusu yaralanmayı; lokal emiş sistemi kimyasal maruziyeti önlemeye hizmet eder.","en":"A machine guard prevents injury; local exhaust ventilation helps prevent chemical exposure."}},{"term":{"tr":"Tehlike","en":"Hazard"},"definition":{"tr":"Zarar verme potansiyeli bulunan kaynak, durum veya faaliyettir.","en":"A source, situation or activity with the potential to cause harm."},"example":{"tr":"Presin hareketli bölgesi, yüksek gürültü ve çözücü buharı birer tehlikedir.","en":"A moving press, high noise and solvent vapour are hazards."}},{"term":{"tr":"Maruziyet","en":"Exposure"},"definition":{"tr":"Çalışanın tehlikeli bir etkenle belirli şiddet, sıklık ve süre boyunca karşılaşmasıdır.","en":"A worker's contact with a hazardous agent at a defined intensity, frequency and duration."},"example":{"tr":"Çözücü buharının bulunduğu ortamda günde dört saat çalışmak kimyasal maruziyettir.","en":"Working four hours a day where solvent vapour is present is chemical exposure."}},{"term":{"tr":"Risk","en":"Risk"},"definition":{"tr":"Bir tehlikenin belirli koşullarda zarara yol açma olasılığı ile sonucun ciddiyetinin birlikte değerlendirilmesidir.","en":"A combined consideration of the likelihood that a hazard causes harm under defined conditions and the severity of that harm."},"example":{"tr":"Koruyucusuz prese sık ve yakın erişim, ciddi el yaralanması riskini yükseltir.","en":"Frequent close access to an unguarded press raises the risk of serious hand injury."}},{"term":{"tr":"Güvenlik ihtiyacı","en":"Safety need"},"definition":{"tr":"Bir tehlike veya kontrol zayıflığı nedeniyle ele alınması gereken somut durumdur.","en":"A concrete condition that requires attention because of a hazard or control weakness."},"example":{"tr":"Koruyucu kilidinin zaman zaman makineyi durdurmaması bir güvenlik ihtiyacıdır.","en":"A guard interlock that sometimes fails to stop the machine is a safety need."}},{"term":{"tr":"Güvenlik müdahalesi","en":"Safety intervention"},"definition":{"tr":"Tehlikeyi ortadan kaldırmak, riski azaltmak veya kontrolü yeniden güvenilir hâle getirmek için verilen karar ve uygulanan eylemdir.","en":"A decision and implemented action that removes a hazard, reduces risk or restores reliable control."},"example":{"tr":"Makineyi durdurmak, kilidi yenilemek ve işlevini test etmek bir müdahale bütünüdür.","en":"Stopping the machine, replacing the interlock and testing its function form one intervention."}},{"term":{"tr":"Kontrol önlemi","en":"Control measure"},"definition":{"tr":"Tehlikeyi ortadan kaldıran veya tehlikeye maruz kalmayı azaltan teknik, yönetsel ya da kişisel koruma düzenlemesidir.","en":"An engineering, administrative or personal-protection measure that eliminates a hazard or reduces exposure."},"example":{"tr":"Tehlikeli kimyasalı değiştirmek, kapalı sistem kurmak ve uygun solunum koruyucu kullanmak farklı kontrol türleridir.","en":"Substitution, enclosure and suitable respiratory protection are different control types."}},{"term":{"tr":"Kritik kontrol","en":"Critical control"},"definition":{"tr":"Ciddi bir olayı önleyen veya sonucunu önemli ölçüde azaltan; başarısızlığı riski belirgin biçimde artıran kontroldür.","en":"A control that prevents a serious event or materially limits its consequence, and whose failure significantly increases risk."},"example":{"tr":"Pres koruyucusunu açınca hareketi güvenli biçimde durduran kilit, ciddi ezilmeyi önleyen kritik kontrol olabilir.","en":"An interlock that safely stops a press when the guard opens may be a critical control against crushing injury."}},{"term":{"tr":"Ciddi sonuç potansiyeli","en":"Serious-outcome potential"},"definition":{"tr":"Gerçek sonuç hafif olsa bile, makul bir koşul farkıyla ölüm, ciddi yaralanma veya kalıcı sağlık kaybı oluşabilme özelliğidir.","en":"The possibility of fatality, serious injury or permanent ill health under a reasonably different circumstance, even when the actual outcome was minor."},"example":{"tr":"Yük birkaç santimetre farkla çalışana çarpmadıysa yaralanma yoktur; ancak ciddi sonuç potansiyeli vardır.","en":"A load missing a worker by centimetres causes no injury but may have serious-outcome potential."}},{"term":{"tr":"Ramak kala olay","en":"Near miss"},"definition":{"tr":"Zarar oluşmayan; ancak küçük bir koşul farkıyla yaralanma, hastalık veya hasar doğurabilecek olaydır.","en":"An event causing no harm but capable of producing injury, illness or damage under slightly different conditions."},"example":{"tr":"Yükün çalışanın yanına düşmesi ramak kala olaydır; olay olmaması kontrolün yeterli olduğunu göstermez.","en":"A load falling beside a worker is a near miss; absence of harm does not prove adequate control."}},{"term":{"tr":"İş hijyeni ve sağlık gözetimi","en":"Occupational hygiene and health surveillance"},"definition":{"tr":"İş hijyeni, fiziksel, kimyasal ve biyolojik etkenleri ölçer ve kontrol eder. Sağlık gözetimi, çalışanın sağlığındaki işle ilişkili değişiklikleri uygun yöntemlerle izler.","en":"Occupational hygiene measures and controls physical, chemical and biological agents. Health surveillance uses suitable methods to monitor work-related changes in worker health."},"example":{"tr":"Gürültü ölçümü iş hijyenine; uygun odyometri izlemi sağlık gözetimine örnektir.","en":"Noise measurement is occupational hygiene; suitable audiometry monitoring is health surveillance."}},{"term":{"tr":"Kanıt","en":"Evidence"},"definition":{"tr":"Bir uygulamanın yalnız söylendiğini değil, tanımlandığını, uygulandığını ve işe yaradığını gösteren doğrulanabilir bilgidir.","en":"Verifiable information showing that a practice is defined, implemented and effective—not merely claimed."},"example":{"tr":"Prosedür tanımı gösterir; saha gözlemi uygulamayı, fonksiyon testi ise kontrolün çalışmasını gösterir.","en":"A procedure shows definition, observation shows implementation and a functional test shows whether the control works."}},{"term":{"tr":"Öncü ve sonuç göstergesi","en":"Leading and lagging measures"},"definition":{"tr":"Öncü gösterge, kontrolün veya sürecin gelecekteki güvenlik sonucunu etkileyen mevcut durumunu izler. Sonuç göstergesi, gerçekleşmiş kaza, hastalık veya kaybı gösterir.","en":"A leading measure monitors the current condition of a control or process that influences future safety outcomes. A lagging measure shows harm or loss that has already occurred."},"example":{"tr":"Çalışan koruyucuların testten geçme oranı öncü; pres kaynaklı yaralanma sayısı sonuç göstergesidir.","en":"The percentage of guards passing functional tests is leading; the number of press injuries is lagging."}},{"term":{"tr":"Karar sahibi ve uygulama sorumlusu","en":"Decision owner and action owner"},"definition":{"tr":"Karar sahibi yetki ve kaynak kararı verir. Uygulama sorumlusu bu kararı sahada yerine getirir; roller aynı kişide olsa bile ayrı ayrı tanımlanır.","en":"The decision owner decides authority and resources. The action owner implements the decision; the roles are defined separately even when held by one person."},"example":{"tr":"Tesis müdürü duruşu onaylar; bakım sorumlusu koruyucuyu kurar.","en":"The plant manager approves downtime; the maintenance owner installs the guard."}},{"term":{"tr":"Üst kademeye taşıma","en":"Escalation"},"definition":{"tr":"Bir konu mevcut yetki veya hedef süre içinde çözülemediğinde daha üst karar düzeyine çıkarılmasıdır.","en":"Moving an issue to a higher decision level when it cannot be resolved within current authority or target time."},"example":{"tr":"Kritik koruyucu arızası vardiya içinde çözülemiyorsa konu aynı gün tesis müdürüne taşınır.","en":"If a critical guard failure cannot be resolved within the shift, it goes to the plant manager that day."}},{"term":{"tr":"Performans standardı","en":"Performance standard"},"definition":{"tr":"Bir kontrolün görevi, kabul edilebilir çalışma sınırı, doğrulama yöntemi, sıklığı ve sorumlusunu tanımlayan ölçütler bütünüdür.","en":"The set of criteria defining a control's function, acceptable operating limit, verification method, frequency and owner."},"example":{"tr":"Koruyucu açıldığında pres belirlenen güvenli süre içinde durmalı ve test her vardiya başında yapılmalıdır.","en":"The press must stop within the specified safe time when the guard opens, and the test is completed at each shift start."}},{"term":{"tr":"Papyon analizi","en":"Bow-tie analysis"},"definition":{"tr":"Tehlikenin ortadaki istenmeyen olaya nasıl ilerleyebileceğini, olayı önleyen kontrolleri ve sonuçları sınırlayan kontrolleri tek görünümde gösteren yöntemdir.","en":"A method showing in one view how a hazard can lead to a central unwanted event, the controls that prevent it and the controls that limit consequences."},"example":{"tr":"Pres için ortadaki olay elin hareketli bölgeye girmesidir; sol tarafta bunu önleyen, sağ tarafta yaralanmayı sınırlayan kontroller gösterilir.","en":"For a press, the central event is a hand entering the moving zone; preventive controls appear to the left and consequence-limiting controls to the right."}},{"term":{"tr":"Normalleşen sapma","en":"Normalisation of deviance"},"definition":{"tr":"Başlangıçta kabul edilemez görülen bir sapmanın hemen zarar doğurmadığı için zamanla olağan ve kabul edilebilir sayılmasıdır.","en":"The gradual acceptance of a deviation once considered unacceptable because it does not immediately produce harm."},"example":{"tr":"Arızalı sensörü her seferinde sıfırlamak olay yaratmadığı için normal iş adımına dönüşür.","en":"Resetting a faulty sensor becomes a normal work step because previous resets caused no event."}},{"term":{"tr":"Psikolojik güvenlik ve adil kültür","en":"Psychological safety and just culture"},"definition":{"tr":"Psikolojik güvenlik, insanların soru ve kaygılarını korkmadan söyleyebilmesidir. Adil kültür, dürüst hata, riskli davranış ve kasıtlı ihlali aynı biçimde değerlendirmez.","en":"Psychological safety allows people to raise questions and concerns without fear. A just culture does not treat honest error, risk-taking behaviour and intentional violation identically."},"example":{"tr":"Arıza bildiren çalışan cezalandırılmaz; olayın bağlamı incelenir ve sorumluluk davranışın niteliğine göre belirlenir.","en":"A worker reporting a fault is not punished; context is examined and accountability reflects the nature of the behaviour."}},{"term":{"tr":"Yatay yayılım","en":"Horizontal deployment"},"definition":{"tr":"Bir olaydan veya iyileştirmeden öğrenilen çözümün benzer iş, ekipman ve bölümlere sistemli biçimde aktarılmasıdır.","en":"Systematically transferring a solution learned from an event or improvement to similar work, equipment and areas."},"example":{"tr":"Bir presin koruyucusu iyileştirildiğinde aynı modeldeki bütün presler kontrol edilir.","en":"When one press guard is improved, every press of the same model is checked."}},{"term":{"tr":"İyileştirme önceliği puanı","en":"Improvement priority score"},"definition":{"tr":"Altı yönetim alanından hangisinin incelenen müdahaleyi daha fazla sınırlayabileceğini karşılaştırmak için bu Navigatörde üretilen göstergedir. Risk puanı, mevzuat puanı veya kesin kök neden kararı değildir.","en":"An indicator generated by this Navigator to compare which of six management areas may be limiting the intervention most. It is not a risk score, regulatory score or definitive root-cause finding."},"example":{"tr":"Karar alanı en yüksek puanı alırsa önce yetki ve karar gecikmesi kanıtları derinleştirilir; bu sonuç tek başına diğer nedenleri dışlamaz.","en":"If the decision area scores highest, authority and delay evidence are examined first; the result does not exclude other causes."}},{"term":{"tr":"Kök neden","en":"Root cause"},"definition":{"tr":"Bir olayın veya başarısız müdahalenin oluşmasına anlamlı katkı sağlayan ve düzeltilmesi tekrarı azaltabilecek temel sistem koşuludur. Karmaşık olaylarda tek bir kök neden bulunmayabilir.","en":"A fundamental system condition that materially contributes to an event or failed intervention and whose correction may reduce recurrence. Complex events may not have one single root cause."},"example":{"tr":"“Operatör koruyucuyu açtı” olay açıklamasıdır; koruyucunun işi yapılamaz hâle getiren tasarımı ve yanıtsız arıza süreci daha temel nedenler olabilir.","en":"“The operator opened the guard” describes an event; unusable guard design and an unanswered fault process may be deeper causes."}},{"term":{"tr":"Etkinlik doğrulaması","en":"Effectiveness verification"},"definition":{"tr":"Aksiyonun tamamlandığını değil, amaçlanan risk azalmasını ve kontrol iyileşmesini gerçekten sağladığını gösteren kontroldür.","en":"A check showing that an action achieved the intended risk reduction and control improvement, not only that it was completed."},"example":{"tr":"Yeni koruyucunun kurulması tamamlanmadır; farklı çalışma koşullarındaki fonksiyon testleri ve arıza eğilimi etkinliği gösterir.","en":"Installing a new guard is completion; functional tests under different conditions and failure trends show effectiveness."}}];
const tocGlossary=[{"term":{"tr":"Kısıt","en":"Constraint"},"definition":{"tr":"Sistemin amacına ulaşmasını o anda en fazla sınırlayan unsur veya mekanizmadır. En büyük tehlike ya da en çok çalışan bölüm demek değildir.","en":"The factor or mechanism currently limiting achievement of the system goal most. It is neither the largest hazard nor the busiest unit."},"example":{"tr":"Tehlike bilinmesine rağmen hiçbir yöneticinin bütçe ve duruş kararı verememesi, karar mekanizmasını kısıt hâline getirebilir.","en":"When a hazard is known but no manager can decide budget and downtime, the decision mechanism may be the constraint."}},{"term":{"tr":"Darboğaz","en":"Bottleneck"},"definition":{"tr":"Talebin insan, zaman, makine veya uzmanlık kapasitesini aştığı fiziksel bir kısıt türüdür.","en":"A physical type of constraint in which demand exceeds people, time, equipment or expertise capacity."},"example":{"tr":"Tek yetkili mühendisin 60 kritik kontrol testine yetişememesi bir darboğazdır.","en":"One authorised engineer being unable to complete 60 critical-control tests is a bottleneck."}},{"term":{"tr":"Politika kısıtı","en":"Policy constraint"},"definition":{"tr":"Kaynak eksikliğinden çok bir kuralın, hedefin, yetki düzeninin veya yerleşik karar alışkanlığının sonucu sınırlamasıdır.","en":"A rule, target, authority arrangement or established decision habit limiting the result more than a resource shortage."},"example":{"tr":"Belirli tutarın altındaki kritik onarımlar için bile üç üst onay gerekmesi politika kısıtı olabilir.","en":"Requiring three senior approvals even for small critical repairs may be a policy constraint."}},{"term":{"tr":"Kısıtı belirleme","en":"Identify the constraint"},"definition":{"tr":"Müdahaleyi en fazla sınırladığına dair en güçlü kanıt bulunan mekanizmayı aday olarak seçmektir.","en":"Selecting the mechanism with the strongest evidence of limiting the intervention as the leading candidate."},"example":{"tr":"Kararların çoğu bütçe onayında bekliyorsa önce karar ve yetki mekanizması incelenir.","en":"If most decisions wait for budget approval, the decision and authority mechanism is examined first."}},{"term":{"tr":"Kısıttan en iyi biçimde yararlanma","en":"Exploit the constraint"},"definition":{"tr":"Yeni kaynak eklemeden önce mevcut kısıtın zamanını, yetkisini veya kapasitesini yalnız en kritik işlere yöneltmektir.","en":"Directing the existing constraint's time, authority or capacity to the most critical work before adding resources."},"example":{"tr":"Yetkili yöneticinin karar gündeminde önce ciddi sonuç potansiyeli taşıyan bulgular ele alınır.","en":"The authorised manager's decision agenda handles serious-outcome-potential findings first."}},{"term":{"tr":"Diğer işleri kısıta göre hizalama","en":"Subordinate other work"},"definition":{"tr":"Diğer süreçlerin önceliklerini, kısıtın kritik işi daha hızlı ve doğru tamamlamasını destekleyecek biçimde düzenlemektir.","en":"Aligning other processes so that the constraint can complete critical work faster and correctly."},"example":{"tr":"Satın alma, bakım ve üretim planı kritik koruyucu kararının bekleme süresini azaltacak ortak takvime bağlanır.","en":"Procurement, maintenance and production planning follow one schedule that reduces waiting for the critical guard decision."}},{"term":{"tr":"Kısıtı yükseltme","en":"Elevate the constraint"},"definition":{"tr":"Mevcut düzenleme yetmediğinde ek yetki, insan, bütçe, mühendislik veya teknoloji kapasitesi sağlamaktır.","en":"Adding authority, people, budget, engineering or technology when current arrangements remain insufficient."},"example":{"tr":"Karar kuyruğu sadeleştirmeye rağmen büyüyorsa ek yetki devri veya yeni teknik kapasite sağlanır.","en":"If the decision queue grows after simplification, additional delegated authority or technical capacity is added."}},{"term":{"tr":"Yeniden değerlendirme","en":"Reassess and repeat"},"definition":{"tr":"Bir kısıt hafiflediğinde eski önceliğe bağlı kalmadan sistemi yeniden incelemek ve yeni sınırlayıcı mekanizmayı aramaktır.","en":"Re-examining the system after one constraint is relieved and searching for the new limiting mechanism without remaining attached to the old priority."},"example":{"tr":"Karar süresi düştükten sonra uygulamalar bakım kapasitesinde birikmeye başlarsa yeni odak kaynak ve kapasite olabilir.","en":"After decision time falls, work may begin to accumulate in maintenance capacity; resource and capacity may then become the new focus."}}];

